import React,{useEffect,useLayoutEffect,useRef,useState} from 'react';
import {Modal} from '../../shared/preferences.tsx';
import {storyAxisPanelsStyle} from './story-axis-panels-style.mjs';

function useSubmission(busy,close){
 const alive=useRef(true),lock=useRef(false),[pending,setPending]=useState(false),[error,setError]=useState('');
 useEffect(()=>{alive.current=true;return()=>{alive.current=false;};},[]);
 const submit=async action=>{if(busy||lock.current)return;lock.current=true;setPending(true);setError('');try{const ok=await action();if(alive.current){if(ok)close();else setError('尚未保存，请核对后重试。');}}catch(e){if(alive.current)setError(e?.message||'请核对输入后再试。');}finally{lock.current=false;if(alive.current)setPending(false);}};
 return {disabled:busy||pending,error,setError,submit,close:()=>{if(!busy&&!lock.current)close();}};
}
function Sheet({title,submission,children}){useLayoutEffect(()=>{const previous=document.activeElement;let selection;try{selection=[previous.selectionStart,previous.selectionEnd,previous.selectionDirection];}catch{}return()=>{if(!previous?.isConnected)return;previous.focus({preventScroll:true});if(selection&&typeof selection[0]==='number')try{previous.setSelectionRange(...selection);}catch{}};},[]);return <Modal title={title} close={submission.close} className="story-axis-sheet"><style>{storyAxisPanelsStyle}</style>{children}{submission.error&&<p className="sap-error" role="alert">{submission.error}</p>}</Modal>;}
function Footer({submission,label='保存',submitDisabled=false,destructiveAction}){return <div className="sap-footer">{destructiveAction}<div className="sap-footer-actions"><button type="button" disabled={submission.disabled} onClick={submission.close}>取消</button><button className="u-primary" type="submit" disabled={submission.disabled||submitDisabled}>{submission.disabled?'保存中…':label}</button></div></div>;}
export function TimelineTrackEditor({track,axis,mode='story',busy=false,onSave,onDelete,deleteDisabled=false,close,onReorder,onSide,onCompact,index=0,total=1,affected=0}){
 const [name,setName]=useState(track?.name||''),[color,setColor]=useState(track?.color||'#7c8d73'),[confirmSide,setConfirmSide]=useState(null),submission=useSubmission(busy,close);const dirty=!!track&&(name!==track.name||color!==track.color);
 return <Sheet title={track?'轨道设置':'新建轨道'} submission={submission}><form className="sap-form" onSubmit={e=>{e.preventDefault();void submission.submit(()=>onSave({name:name.trim(),color}));}}><p className="sap-intro">轨道用于自由命名和分组。共享轨道的名称和颜色在两个时间视图中更新，卡片时间与位置各自独立。</p><label>轨道名称<input required autoFocus maxLength={80} value={name} onChange={e=>setName(e.target.value)}/></label><label className="sap-color">轨道颜色<input type="color" value={color} onChange={e=>setColor(e.target.value)}/></label>{track&&onReorder&&<section className="sap-track-layout"><h4>{mode==='story'?'故事':'叙述'}视图排列</h4><p>仅调整当前视图的轨道分组顺序，不改变卡片时间或另一视图的位置。</p><div><button type="button" disabled={submission.disabled||dirty||index===0} onClick={()=>submission.submit(()=>onReorder(-1))}>↑ 上移</button><span>{index+1} / {total}</span><button type="button" disabled={submission.disabled||dirty||index===total-1} onClick={()=>submission.submit(()=>onReorder(1))}>↓ 下移</button></div>{dirty&&<small>先保存名称或颜色，再调整排列。</small>}</section>}{track&&onSide&&<section className="sap-track-layout"><h4>整条轨道摆放</h4><p>影响本轨道已安排的 {affected} 张卡片，并设为以后新卡片的默认位置；日期与时长不变，之后仍可单独移动。</p><div>{[['above','全部放到轴上'],['below','全部放到轴下']].map(([side,label])=><button type="button" key={side} disabled={submission.disabled||dirty} onClick={()=>setConfirmSide(side)}>{label}</button>)}</div>{confirmSide&&<div className="sap-track-confirm"><span>{affected?`将 ${affected} 张卡片移至时间轴${confirmSide==='above'?'上方':'下方'}，并设置默认位置？`:`将空轨道的默认位置设为时间轴${confirmSide==='above'?'上方':'下方'}？`}</span><button type="button" disabled={submission.disabled} onClick={()=>submission.submit(()=>onSide(confirmSide))}>确认移动</button><button type="button" onClick={()=>setConfirmSide(null)}>取消</button></div>}</section>}{track&&onCompact&&<button type="button" disabled={submission.disabled||dirty} onClick={()=>submission.submit(onCompact)}>收起轨道空行</button>}{track&&onDelete&&<button type="button" className="sap-danger" disabled={submission.disabled||deleteDisabled||(axis?.tracks?.length??2)<=1} onClick={()=>submission.submit(onDelete)}>删除轨道</button>}<Footer submission={submission} submitDisabled={!name.trim()}/></form></Sheet>;
}
